export interface MCQ {
  id: string;
  question: string;
  options: string[];
  answer: number;
  explanation: string;
  source: string;
}

export const sampleQuiz: MCQ[] = [
  { id: "m1", question: "Which scheduling algorithm can cause starvation of long processes?", options: ["Round Robin", "Shortest Job First", "First Come First Serve", "Multilevel Feedback with aging"], answer: 1, explanation: "SJF always picks the shortest job, so long jobs may wait indefinitely if short jobs keep arriving.", source: "OS Galvin, p. 142" },
  { id: "m2", question: "In Round Robin, what happens when the time quantum is very large?", options: ["It behaves like FCFS", "It behaves like SJF", "Throughput becomes zero", "Context switches increase"], answer: 0, explanation: "With a huge quantum, every process finishes within its slice, so RR degenerates to FCFS.", source: "OS Galvin, p. 146" },
  { id: "m3", question: "Which condition is NOT necessary for deadlock?", options: ["Mutual exclusion", "Hold and wait", "Preemption", "Circular wait"], answer: 2, explanation: "The necessary condition is NO preemption. Allowing preemption actually helps prevent deadlock.", source: "OS Galvin, p. 189" },
  { id: "m4", question: "Belady's anomaly is observed in which page replacement algorithm?", options: ["LRU", "Optimal", "FIFO", "LFU"], answer: 2, explanation: "FIFO can show more page faults with more frames — this is Belady's anomaly.", source: "OS Galvin, p. 201" },
  { id: "m5", question: "A process control block (PCB) does NOT contain:", options: ["Program counter", "CPU registers", "Compiler version", "Process state"], answer: 2, explanation: "The PCB stores process state, PC, registers, scheduling and memory info — not compiler details.", source: "OS Galvin, p. 108" },
];

/** Count correct answers. Unanswered questions (undefined) count as wrong. */
export function scoreQuiz(questions: MCQ[], answers: Record<string, number | undefined>) {
  const correct = questions.filter((q) => answers[q.id] === q.answer).length;
  return { correct, total: questions.length, percent: questions.length ? Math.round((correct / questions.length) * 100) : 0 };
}
